def rotate_matrix(matrix):
    """
    Rotate a matrix 90 degrees clockwise.
    Returns an empty list if the matrix is empty or has zero columns.
    """
    if not matrix or not matrix[0]:
        return []

    rows = len(matrix)
    cols = len(matrix[0])

    # Create a new list of lists
    result = []
    for r in range(rows):
        # Take the last r columns and reverse them
        # Then take the first r columns and reverse them
        # This is equivalent to rotating 90 degrees clockwise
        result.append(matrix[r][cols - 1 - r])

    return result
